# تكرار تحية بسيطة 3 مرات
for i in range(3):
    print("أهلاً بك!")

fruits = ["تفاح", "موز", "برتقال"]
for f in fruits:
    print(f)

n = 1
while True:
    print(n)
    if n == 2:
        break
    n += 1

for i in range(4):
    if i == 2:
        continue
    print(i)

for x in range(2):
    print(x)
else:
    print("انتهت الحلقة!")

# Repeat a simple greeting 3 times
for i in range(3):
    print("Hello!")

fruits = ["apple", "banana", "orange"]
for f in fruits:
    print(f)

n = 1
while True:
    print(n)
    if n == 2:
        break
    n += 1

for i in range(4):
    if i == 2:
        continue
    print(i)

for x in range(2):
    print(x)
else:
    print("Loop completed!")
